// Types for the JSON content in `src/data/`. Generated by scripts/reference/build-data.mjs.

export interface MediaRef {
	src: string;
	alt: string;
}

export interface Term {
	slug: string;
	label: string;
}

export interface PortableTextSpan {
	_type: "span";
	text: string;
}

export interface PortableTextBlock {
	_type: "block";
	style: "normal" | "h1" | "h2" | "h3" | "h4" | "blockquote";
	children: PortableTextSpan[];
}

export type PortableText = PortableTextBlock[];

// ---------------------------------------------------------------- rich page blocks
//
// Produced by scripts/reference/extract-page-content.mjs from the captured
// WordPress pages. One block per Elementor widget, in document order.

export interface PageHeading {
	type: "heading";
	level: 1 | 2 | 3 | 4 | 5 | 6;
	text: string;
	html?: string;
}

export interface PageParagraph {
	type: "paragraph";
	html: string;
	dropCap?: boolean;
}

export interface PageImage {
	type: "image";
	src: string;
	alt: string;
	background?: boolean;
}

export interface PageButton {
	type: "button";
	label: string;
	href: string;
	icon?: string;
}

export interface PageDivider {
	type: "divider";
}

export interface PageIconBox {
	type: "iconBox";
	icon: string;
	title: string;
	text: string;
}

export interface PageIcon {
	type: "icon";
	icon: string;
}

export interface PageVideo {
	type: "video";
	src: string;
	title?: string;
}

export interface PageHtml {
	type: "html";
	html: string;
}

export interface PageListing {
	type: "listing";
	listingId: string | null;
	postType: string | null;
	limit: number | null;
	columns: number | null;
}

export interface PageHero {
	type: "hero";
	title: string;
	image: string;
	variant: "photo" | "pattern";
}

export type PageBlock =
	| PageHeading
	| PageParagraph
	| PageImage
	| PageButton
	| PageDivider
	| PageIconBox
	| PageIcon
	| PageVideo
	| PageHtml
	| PageListing
	| PageHero;

export type PageContent = PageBlock[];

export interface BaseEntry {
	id: string;
	slug: string;
	status: string;
	order?: number;
	publishedAt?: string;
	terms?: Record<string, Term[]>;
}

export interface Service extends BaseEntry {
	title: string;
	featured_image: MediaRef | null;
	price_label: string | null;
	audience_label: string | null;
	format: string | null;
	notice: string | null;
	booking_url: string | null;
	content: PortableText;
}

export interface ResourceCta {
	label: string;
	url: string;
}

export interface Resource extends BaseEntry {
	title: string;
	featured_image: MediaRef | null;
	badge_label: string | null;
	ctas: ResourceCta[];
	video_url: string | null;
	excerpt: string | null;
	content: PortableText;
}

export interface Testimonial extends BaseEntry {
	title: string | null;
	quote: string | null;
	author: string | null;
}

export interface Post extends BaseEntry {
	title: string;
	excerpt: string | null;
	featured_image: MediaRef | null;
	content: PortableText;
}

export interface Page extends BaseEntry {
	title: string;
	hero_title: string | null;
	hero_image: MediaRef | null;
	side_image: MediaRef | null;
	content: PageContent;
}

export interface MenuItem {
	type: string;
	label: string;
	url: string;
	children?: MenuItem[];
}

export interface Menu {
	name: string;
	label: string;
	items: MenuItem[];
}

export interface Banner {
	layout: "portrait" | "overlay";
	title: string;
	subtitle: string;
	buttonLabel: string;
	buttonUrl: string;
	image: string;
	mobileImage?: string;
}

export interface SiteSettings {
	title: string;
	tagline: string;
	url: string;
	logo: MediaRef | null;
	social: Record<string, string>;
}

export interface Taxonomy {
	name: string;
	label: string;
	labelSingular: string;
	terms: Term[];
}
